"""Parse INI text."""
sections: dict[str, dict[str, str]] = {}
section = key = None
for lineno, line in enumerate(text.splitlines(), 1):
    stripped = line.strip()
    if not stripped or stripped[0] in "#;":
        key = None
    elif key is not None and line[0].isspace():
        section[key] += "\n" + stripped
    elif stripped[0] == "[" and stripped[-1] == "]":
        section = sections.setdefault(stripped[1:-1].strip(), {})
        key = None
    else:
        match = re.search("[=:]", stripped)
        if match is None:
            raise ParseError(lineno, f"cannot parse {stripped!r}")
        if section is None:
            raise ParseError(lineno, "key before any section")
        key = stripped[: match.start()].strip().lower()
        if not key:
            raise ParseError(lineno, "empty key")
        section[key] = stripped[match.end() :].strip()

done: dict[tuple[str, str], str] = {}

def resolve(name: str, key: str, active: tuple[tuple[str, str], ...]) -> str:
    ref = (name, key)
    if ref in done:
        return done[ref]
    if ref in active:
        raise InterpolationError(f"cycle at ${{{name}:{key}}}")
    if name not in sections or key not in sections[name]:
        raise InterpolationError(f"missing reference ${{{name}:{key}}}")

    def replace(match: re.Match) -> str:
        if match.group(1) is None:
            return "$"
        other, sep, other_key = match.group(1).rpartition(":")
        return resolve(
            other.strip() if sep else name,
            other_key.strip().lower(),
            active + (ref,),
        )

    done[ref] = _REFERENCE.sub(replace, sections[name][key])
    return done[ref]

return {
    name: {key: resolve(name, key, ()) for key in keys}
    for name, keys in sections.items()
}

